// 1. Obtener la lista de categorías únicas traídas de Google Sheets
const items = $input.all();
const categoriasSet = new Set();

items.forEach(item => {
  const cat = item.json.categoria || item.json.Categoria || item.json.CATEGORIA;
  if (cat) {
    categoriasSet.add(cat.trim());
  }
});

const categorias = Array.from(categoriasSet);

// 2. Mapeo de emojis por categoría para mantenerlo estético
const emojisMap = {
  'BEBIDAS': '🥤',
  'SNACKS': '🍿',
  'COMIDAS': '🍔',
  'POSTRES': '🍰'
};

// 3. Crear las filas de botones para cada categoría
const keyboard = [];

categorias.forEach(cat => {
  const emoji = emojisMap[cat.toUpperCase()] || '🍽️';
  keyboard.push([
    {
      text: `${emoji} ${cat.toUpperCase()}`,
      callback_data: `CAT_${cat.toUpperCase()}`
    }
  ]);
});

// 4. Agregar de forma limpia el acceso directo al carrito (opcional)
keyboard.push([
  { text: "🛒 Ver mi Carrito", callback_data: "VER_CARRITO" }
]);

// 5. Estructurar el mensaje de salida
const textoMensaje = "🛒 *MENÚ DE OPCIONES*\n\nPor favor, selecciona una categoría para ver los productos disponibles:";

return [{
  json: {
    texto_mensaje: textoMensaje,
    reply_markup: {
      inline_keyboard: keyboard
    }
  }
}];

