// 1. Obtener el callback_data enviado por Telegram (ej: CAT_BEBIDAS)
const callbackData = $('Telegram Trigger').item.json.callback_query?.data || '';

// 2. Extraer el texto base quitando 'CAT_'
const rawCat = callbackData.replace('CAT_', '').trim();

// 3. Normalizar formato tipo Oración/Título (Ejemplo: "BEBIDAS" -> "Bebidas")
const categoriaFormateada = rawCat ? rawCat.charAt(0).toUpperCase() + rawCat.slice(1).toLowerCase() : '';

return [{
  json: {
    categoria_seleccionada: rawCat,               // Entrega "BEBIDAS"
    categoria: categoriaFormateada,               // Entrega "Bebidas"
    categoria_lower: rawCat.toLowerCase()         // Entrega "bebidas"
  }
}];

// 1. Extraer la categoría elegida por el usuario
let catSeleccionada = '';
try {
  const extraida = $('EXTRAER CATEGORIA').first().json;
  catSeleccionada = extraida.categoria || extraida.categoria_seleccionada || '';
} catch (e) {
  catSeleccionada = '';
}

// 2. Extraer los ítems traídos por Google Sheets sin perder referencias
const itemsRaw = $input.all().map(i => i.json);

// 3. Filtrar reconociendo cualquier nombre de columna o variaciones de minúsculas
const catBuscada = catSeleccionada.toString().trim().toUpperCase();

const productosCoincidentes = itemsRaw.filter(item => {
  const catProducto = (item.categoria || item.Categoria || item.CATEGORIA || '').toString().trim().toUpperCase();
  return catBuscada ? (catProducto === catBuscada || catProducto.includes(catBuscada)) : true;
});

// Si el filtro estricto no encuentra, toma la lista completa devuelta
const productosFinales = productosCoincidentes.length > 0 ? productosCoincidentes : itemsRaw;

// 4. Construir la respuesta para Telegram
const nombreCategoria = catSeleccionada ? catSeleccionada.toUpperCase() : 'SELECCIONADA';
let textoMensaje = `📌 *CATEGORÍA: ${nombreCategoria}*\n\n`;
const keyboard = [];

productosFinales.forEach(p => {
  // Ignorar filas de encabezados o vacías
  const idProd = p.id_producto || p.id || p.ID || p.idProducto;
  const nombreProd = p.nombre || p.Nombre || p.PRODUCTO || p.producto;
  const precioProd = Number(p.precio || p.Precio || p.PRECIO || 0);

  if (nombreProd) {
    textoMensaje += `✨ *${nombreProd}*\n`;
    textoMensaje += `💲 Precio: *$${precioProd.toLocaleString('es-CO')}*\n\n`;

    keyboard.push([
      {
        text: `➕ Añadir ${nombreProd} ($${precioProd.toLocaleString('es-CO')})`,
        callback_data: `SELECTPROD_${idProd || nombreProd}`
      }
    ]);
  }
});

// 5. Botón de regreso que dispara la Routing Rule de menú
keyboard.push([
  {
    text: "⬅️ Volver a Categorías",
    callback_data:"NUEVO_PEDIDO"
  }
]);

return [{
  json: {
    texto_mensaje: textoMensaje,
    reply_markup: {
      inline_keyboard: keyboard
    }
  }
}];

// 1. Extraer el ID enviado por Telegram en el callback_data (ej. P004)
const callbackData = $('Telegram Trigger').item.json.callback_query?.data || '';
const idProducto = callbackData.replace('SELECTPROD_IDX_', '').replace('SELECTPROD_', '').trim();

// 2. Obtener la lista de productos de Google Sheets
const productos = $input.all().map(i => i.json);

// 3. Buscar en JS el producto que coincida exactamente con ese ID
const productoSel = productos.find(p => {
  const idP = String(p.id_producto || p.id || p.ID || p.Id || '').trim();
  return idP.toUpperCase() === idProducto.toUpperCase();
}) || productos[0] || {};

// 4. Mapear Nombre y Precio con variaciones de columnas
const nombre = productoSel.nombre || productoSel.Nombre || productoSel.PRODUCTO || 'Producto';
const precioBruto = productoSel.precio || productoSel.Precio || productoSel.PRECIO || 0;
const precio = Number(precioBruto).toLocaleString('es-CO');

// 5. Construir el mensaje
const textoMensaje = `✨ *${nombre}*\n💲 *Precio unitario:* $${precio}\n\n*¿Cuántas unidades deseas agregar?*`;

// Reemplaza el botón inferior en el array keyboard por este:
const keyboard = [
  [
    { text: "1️⃣", callback_data: `ADD_${idProducto}_QTY_1` },
    { text: "2️⃣", callback_data: `ADD_${idProducto}_QTY_2` },
    { text: "3️⃣", callback_data: `ADD_${idProducto}_QTY_3` }
  ],
  [
    { text: "4️⃣", callback_data: `ADD_${idProducto}_QTY_4` },
    { text: "5️⃣", callback_data: `ADD_${idProducto}_QTY_5` }
  ],
  [
    { text: "⬅️ Volver a Categorías", callback_data: "NUEVO_PEDIDO" }
  ]
];

return [{
  json: {
    texto_mensaje: textoMensaje,
    reply_markup: {
      inline_keyboard: keyboard
    }
  }
}];

// 1. Extraer ID del producto y cantidad del callback_data (ej: ADD_P004_QTY_2)
const callbackData = $('Telegram Trigger').item.json.callback_query?.data || '';
const partes = callbackData.split('_QTY_');
const idProducto = partes[0].replace('ADD_', '').trim();
const cantidad = Number(partes[1] || 1);

const telegramId = $('Telegram Trigger').item.json.callback_query?.from?.id || $('Telegram Trigger').item.json.message?.from?.id;

// 2. Traer productos de OBTENER MENU CARRITO
const productos = $input.all().map(i => i.json);

// Buscar el producto sin importar mayúsculas/minúsculas ni variaciones de columna
const productoSel = productos.find(p => {
  const idP = String(p.id_producto || p.id || p.ID || '').trim();
  return idP.toUpperCase() === idProducto.toUpperCase();
}) || productos[0] || {};

const nombre = productoSel.nombre || productoSel.Nombre || productoSel.PRODUCTO || 'Producto';
const precioUnitario = Number(productoSel.precio || productoSel.Precio || productoSel.PRECIO || 0);
const subtotal = precioUnitario * cantidad;

// 3. Leer carrito actual desde el Router Principal
let carritoActual = [];
try {
  const carritoRaw = $('ROUTER PRINCIPAL').item.json.carrito_temporal;
  if (carritoRaw) {
    carritoActual = typeof carritoRaw === 'string' ? JSON.parse(carritoRaw) : carritoRaw;
  }
} catch (e) {
  carritoActual = [];
}

// 4. Agregar o actualizar ítem
const itemExistente = carritoActual.find(i => String(i.id).toUpperCase() === idProducto.toUpperCase());
if (itemExistente) {
  itemExistente.cantidad += cantidad;
  itemExistente.subtotal = itemExistente.cantidad * precioUnitario;
  itemExistente.nombre = nombre; // Asegurar nombre real
  itemExistente.precio = precioUnitario; // Asegurar precio real
} else {
  carritoActual.push({
    id: idProducto,
    nombre: nombre,
    precio: precioUnitario,
    cantidad: cantidad,
    subtotal: subtotal
  });
}

// 5. Mensaje de confirmación con botones mapeados a tu Switch
const precioFormateado = subtotal.toLocaleString('es-CO');
const textoMensaje = `🛍️ *¡Añadido al carrito con éxito!*\n\n✨ *${cantidad}x ${nombre}*\n💲 Subtotal: *$${precioFormateado}*\n\n¿Qué deseas hacer ahora?`;

const keyboard = [
  [
    { text: "⬅️ Ver más Categorías", callback_data: "NUEVO_PEDIDO" },
    { text: "🛒 Ver mi Carrito", callback_data: "VER_CARRITO" }
  ]
];

return [{
  json: {
    telegram_id: telegramId,
    carrito_json: JSON.stringify(carritoActual),
    texto_mensaje: textoMensaje,
    reply_markup: {
      inline_keyboard: keyboard
    }
  }
}];

// 1. Obtener los datos del usuario desde Google Sheets
const items = $input.all();
const usuarioData = (items.length > 0 && items[0].json) ? items[0].json : {};

// 2. Extraer y parsear el carrito_temporal
let carritoRaw = usuarioData.carrito_temporal || usuarioData.CARRITO_TEMPORAL || usuarioData.carrito || '';

let carrito = [];
try {
  if (carritoRaw) {
    carrito = typeof carritoRaw === 'string' ? JSON.parse(carritoRaw) : carritoRaw;
  }
} catch (e) {
  carrito = [];
}

// 3. Si el carrito está vacío
if (!carrito || !Array.isArray(carrito) || carrito.length === 0) {
  return [{
    json: {
      texto_mensaje: "🛒 *TU CARRITO DE COMPRAS*\n\n*(Tu carrito está vacío actualmente)*\n\n¿Deseas explorar nuestro menú para empezar a comprar?",
      reply_markup: {
        inline_keyboard: [
          [{ text: "📋 Ver Menú / Categorías", callback_data: "NUEVO_PEDIDO" }]
        ]
      }
    }
  }];
}

// 4. Si hay productos, armar el resumen
let textoMensaje = "🛒 *TU CARRITO DE COMPRAS*\n\n";
let totalGeneral = 0;

carrito.forEach((item) => {
  const nombre = item.nombre || 'Producto';
  const cant = Number(item.cantidad || 1);
  const precioUnitario = Number(item.precio || 0);
  const subtotalItem = Number(item.subtotal || (precioUnitario * cant));

  totalGeneral += subtotalItem;

  textoMensaje += `✨ *${cant}x ${nombre}*\n`;
  textoMensaje += `💲 $${subtotalItem.toLocaleString('es-CO')} _($${precioUnitario.toLocaleString('es-CO')} c/u)_\n\n`;
});

textoMensaje += `───────────────────\n`;
textoMensaje += `💰 *TOTAL A PAGAR:* 💲 *$${totalGeneral.toLocaleString('es-CO')}*\n\n`;
textoMensaje += `¿Qué deseas hacer con tu pedido?`;

// 5. Botones alineados con las reglas del Switch
const keyboard = [
  [
    { text: "⬅️ Seguir Comprando", callback_data: "NUEVO_PEDIDO" }
  ],
  [
    { text: "✅ Confirmar Compra", callback_data: "CONFIRMAR_COMPRA" }
  ],
  [
    { text: "🗑️ Vaciar / Cancelar Compra", callback_data: "CANCELAR_PEDIDO" }
  ]
];

return [{
  json: {
    texto_mensaje: textoMensaje,
    reply_markup: {
      inline_keyboard: keyboard
    }
  }
}];

// 1. Obtener el chat_id / telegram_id de forma ultra-segura
let telegramId = "";
try {
  const trigger = $('Telegram Trigger').first().json;
  telegramId = trigger.callback_query?.from?.id || 
               trigger.message?.from?.id || 
               trigger.from?.id || "";
} catch(e) {
  telegramId = "";
}

// 2. Obtener los datos del carrito desde el input o sesión previa
const datosInput = $input.first().json;

let carritoRaw = datosInput.carrito_temporal || datosInput.CARRITO_TEMPORAL || "";

if (!carritoRaw) {
  try {
    carritoRaw = $('BUSCAR SESION').first().json.carrito_temporal || "";
  } catch(e) {
    carritoRaw = "";
  }
}

let carrito = [];
try {
  carrito = typeof carritoRaw === 'string' ? JSON.parse(carritoRaw) : carritoRaw;
} catch(e) {
  carrito = [];
}

// 3. Si el carrito está vacío
if (!carrito || !Array.isArray(carrito) || carrito.length === 0) {
  return [{
    json: {
      chat_id: telegramId,
      texto_mensaje: "⚠️ *Tu carrito está vacío.* Selecciona algunos productos antes de proceder a la compra.",
      reply_markup: {
        inline_keyboard: [
          [{ text: "📋 Ver Menú de Categorías", callback_data: "VER_CATEGORIAS" }]
        ]
      }
    }
  }];
}

// 4. Cálculos de Liquidación
let subtotal = 0;
let resumenProductos = "";

carrito.forEach(item => {
  const cant = Number(item.cantidad || 1);
  const precioUnitario = Number(item.precio || 0);
  const itemSubtotal = Number(item.subtotal || (cant * precioUnitario));

  subtotal += itemSubtotal;
  resumenProductos += `• *${cant}x ${item.nombre}* — $${itemSubtotal.toLocaleString('es-CO')}\n`;
});

const porcentajeIVA = 0.19; // 19% IVA Colombia
const valorIVA = Math.round(subtotal * porcentajeIVA);
const totalPagar = subtotal + valorIVA;

// Puntos de lealtad (1 punto por cada $1.000)
const puntosGanados = Math.floor(totalPagar / 1000);

// 5. Mensaje estético
let textoMensaje = `🧾 *RESUMEN DE TU PEDIDO*\n\n`;
textoMensaje += `📋 *Productos Seleccionados:*\n${resumenProductos}\n`;
textoMensaje += `───────────────────\n`;
textoMensaje += `💵 *Subtotal:* $${subtotal.toLocaleString('es-CO')}\n`;
textoMensaje += `🏛️ *IVA (19%):* $${valorIVA.toLocaleString('es-CO')}\n`;
textoMensaje += `💰 *TOTAL A PAGAR:* *$${totalPagar.toLocaleString('es-CO')}*\n`;
textoMensaje += `───────────────────\n`;
textoMensaje += `🎁 *¡Con esta compra acumulas ${puntosGanados} Puntos de Lealtad!* 🎉\n\n`;
textoMensaje += `¿Deseas proceder al pago o revisar tu pedido?`;

// 6. Botones: Ir a Pagar / Editar Pedido (Ir al carrito)
const keyboard = [
  [
    { text: "💳 Ir a Pagar", callback_data: "IR_A_PAGAR" }
  ],
  [
    { text: "✏️ Editar Pedido", callback_data: "VER_CARRITO" }
  ]
];

return [{
  json: {
    chat_id: telegramId,
    subtotal: subtotal,
    iva: valorIVA,
    total_pagar: totalPagar,
    puntos_ganados: puntosGanados,
    texto_mensaje: textoMensaje,
    reply_markup: {
      inline_keyboard: keyboard
    }
  }
}];

// Obtener el ID del cliente
let telegramId = "";
try {
  const trigger = $('Telegram Trigger').first().json;
  telegramId = trigger.callback_query?.from?.id || trigger.message?.from?.id || "";
} catch(e) {
  telegramId = "";
}

let texto = `💳 *SELECCIONA TU MÉTODO DE PAGO*\n\n`;
texto += `¿Cómo deseas realizar el pago de tu pedido?`;

const keyboard = [
  [
    { text: "📲 Nequi / PSE", callback_data: "PAGO_NEQUI" },
    { text: "💵 Efectivo contra entrega", callback_data: "PAGO_EFECTIVO" }
  ],
  [
    { text: "⬅️ Volver a Resumen", callback_data: "CONFIRMAR_COMPRA" }
  ]
];

return [{
  json: {
    chat_id: telegramId,
    texto_mensaje: texto,
    reply_markup: {
      inline_keyboard: keyboard
    }
  }
}];

const trigger = $('Telegram Trigger').first().json;
let telegramId = trigger.callback_query?.from?.id || trigger.message?.from?.id || "";
let callbackData = trigger.callback_query?.data || "";

let metodoElegido = (callbackData === 'PAGO_NEQUI') ? 'Nequi / PSE' : 'Efectivo contra entrega';

let texto = `🛵 *TIPO DE ENTREGA*\n\n`;
texto += `Pago seleccionado: *${metodoElegido}*\n\n`;
texto += `¿Cómo deseas recibir tu pedido?`;

const keyboard = [
  [
    { text: "🏠 Recoger en Local", callback_data: "ENVIO_LOCAL" },
    { text: "🛵 Envío a Domicilio", callback_data: "ENVIO_DOMICILIO" }
  ],
  [
    { text: "⬅️ Cambiar Método de Pago", callback_data: "IR_A_PAGAR" }
