// 1. Obtener datos del Trigger y de la búsqueda de Sesión
const trigger = $('Telegram Trigger').first().json;
let telegramId = trigger.message?.from?.id || trigger.callback_query?.from?.id || "";

// Traer la fila completa de la sesión/usuario que viene de Google Sheets
let sesion = {};
try {
  sesion = $('BUSCAR SESION').first().json || {};
} catch(e) {
  sesion = {};
}

// 2. Extraer campos capturados (con valores por defecto si alguno no se encontró)
const correoIngresado = trigger.message?.text || sesion.correo || "No registrado";
const telefonoIngresado = sesion.telefono || "No registrado";
const direccionIngresada = sesion.direccion || "Recoge en Local";
const tipoEnvio = sesion.tipo_envio || (sesion.direccion ? "Domicilio" : "Local");
const metodoPago = sesion.metodo_pago || "Efectivo / Nequi";

// 3. Obtener Carrito y Totales
let carrito = [];
try {
  carrito = typeof sesion.carrito_temporal === 'string' ? JSON.parse(sesion.carrito_temporal) : (sesion.carrito_temporal || []);
} catch(e) {
  carrito = [];
}

let subtotal = 0;
let resumenProductos = "";
carrito.forEach(item => {
  const cant = Number(item.cantidad || 1);
  const precio = Number(item.precio || 0);
  const totalItem = Number(item.subtotal || (cant * precio));
  subtotal += totalItem;
  resumenProductos += `• *${cant}x ${item.nombre}* — $${totalItem.toLocaleString('es-CO')}\n`;
});

const valorIVA = Math.round(subtotal * 0.19);
const totalPagar = subtotal + valorIVA;

// 4. Generar ID Único de Pedido
const randomId = Math.floor(1000 + Math.random() * 9000);
const idPedido = `PED-${randomId}`;

// 5. Armar la Ficha Consolidada Completa
let texto = `📋 *RESUMEN FINAL Y CONFIRMACIÓN DE DATOS*\n\n`;
texto += `🏷️ *Orden:* \`${idPedido}\`\n`;
texto += `👤 *Cliente:* Yenifer Cortez\n`;
texto += `📞 *Teléfono:* ${telefonoIngresado}\n`;
texto += `📧 *Correo:* ${correoIngresado}\n`;
texto += `🛵 *Tipo de Entrega:* ${tipoEnvio}\n`;
if (tipoEnvio.toLowerCase().includes("domicilio") || sesion.direccion) {
  texto += `📍 *Dirección:* ${direccionIngresada}\n`;
}
texto += `───────────────────\n`;
texto += `📋 *Productos:*\n${resumenProductos}`;
texto += `───────────────────\n`;
texto += `💵 *Subtotal:* $${subtotal.toLocaleString('es-CO')}\n`;
texto += `🏛️ *IVA (19%):* $${valorIVA.toLocaleString('es-CO')}\n`;
texto += `💳 *Método de Pago:* ${metodoPago}\n`;
texto += `💰 *TOTAL A PAGAR:* *$${totalPagar.toLocaleString('es-CO')}*\n\n`;
texto += `¿Confirmas que toda la información es correcta para enviar el pedido al restaurante?`;

const keyboard = [
  [
    { text: "✅ Confirmar y Enviar Pedido", callback_data: `FINALIZAR_${idPedido}` }
  ],
  [
    { text: "✏️ Modificar Datos", callback_data: "IR_A_PAGAR" }
  ]
];

return [{
  json: {
    chat_id: telegramId,
    id_pedido: idPedido,
    subtotal: subtotal,
    iva: valorIVA,
    total_pagar: totalPagar,
    metodo_pago: metodoPago,
    tipo_envio: tipoEnvio,
    direccion: direccionIngresada,
    telefono: telefonoIngresado,
    correo: correoIngresado,
    texto_mensaje: texto,
    reply_markup: { inline_keyboard: keyboard }
  }
}];

const fila = $input.first().json;

const idPedido = fila.id_pedido || "";
const idUsuario = fila.id_usuario; // Tu telegram_id
const estado = (fila.estado || "").toUpperCase().trim();

let mensaje = "";

if (estado === "EN PREPARACION") {
  mensaje = `👨‍🍳 *¡TU PEDIDO ESTÁ EN PREPARACIÓN!*\n\n` +
            `🔖 *Orden:* \`${idPedido}\`\n\n` +
            `El restaurante ya está preparando tu orden. ¡Te avisaremos cuando salga! ✨`;
} else if (estado === "ENVIADO" || estado === "EN CAMINO") {
  mensaje = `🛵 *¡TU PEDIDO VA EN CAMINO!*\n\n` +
            `🔖 *Orden:* \`${idPedido}\`\n\n` +
            `Tu domicilio ha sido despachado. ¡Atento/a a la entrega! 💨`;
} else if (estado === "ENTREGADO") {
  mensaje = `🎉 *¡PEDIDO ENTREGADO!*\n\n` +
            `🔖 *Orden:* \`${idPedido}\`\n\n` +
            `¡Gracias por tu compra! Esperamos que lo disfrutes. 🍽️`;
} else {
  return []; // Si no es uno de estos estados, no envía nada
}

return [{
  json: {
    chat_id: idUsuario,
    texto_mensaje: mensaje
  }
}];

// Obtener fecha y hora actual ajustada a Colombia (America/Bogota, UTC-5)
const ahora = new Date();
const bogotaString = ahora.toLocaleString("en-US", { timeZone: "America/Bogota" });
const fechaBogota = new Date(bogotaString);

const diaSemana = fechaBogota.getDay(); // 0: Domingo, 1: Lunes, ..., 5: Viernes, 6: Sábado
const horaActual = fechaBogota.getHours(); // Hora en formato 0 - 23

// Regla: Lunes (1) a Viernes (5) Y entre las 8:00 AM (8) y las 4:59 PM (hora < 17)
